import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./manageUserAccounts.css";
import AdminSidebar from "../components/AdminSideBar";
import Navbar from "../components/navbar";
import Footer from "../components/footer";

function ManageUserAccounts() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [role, setRole] = useState("");
  const [registrationNumber, setRegistrationNumber] = useState("");
  const [password, setPassword] = useState("");

  const [students, setStudents] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [evaluators, setEvaluators] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");

  const [viewStudents, setViewStudents] = useState(false);
  const [viewSupervisors, setViewSupervisors] = useState(false);
  const [viewEvaluators, setViewEvaluators] = useState(false);

  const [editingId, setEditingId] = useState(null);
  const [editingType, setEditingType] = useState("");

  // Fetch all users on component mount
  useEffect(() => {
    fetchAllUsers();
  }, []);

  const fetchAllUsers = async () => {
    setIsLoading(true);
    try {
      // Fetch all users
      const usersResponse = await axios.get("http://localhost:5000/api/user");
      const allUsers = usersResponse.data;

      // Fetch additional details for each role
      const studentsResponse = await axios.get("http://localhost:5000/api/student");
      const supervisorsResponse = await axios.get("http://localhost:5000/api/facultyadvisor");
      const evaluatorsResponse = await axios.get("http://localhost:5000/api/evaluator");

      // Combine user data with role-specific data
      const combinedStudents = studentsResponse.data.map(student => {
        const user = allUsers.find(u => u._id === student.userId);
        return {
          ...student,
          ...user,
          id: student._id,
          userId: user._id,
          name: student.studentName,
          role: "Student"
        };
      });

      const combinedSupervisors = supervisorsResponse.data.map(supervisor => {
        const user = allUsers.find(u => u._id === supervisor.userId);
        return {
          ...supervisor,
          ...user,
          id: supervisor._id,
          userId: user._id,
          name: supervisor.Name,
          role: "Supervisor"
        };
      });

      const combinedEvaluators = evaluatorsResponse.data.map(evaluator => {
        const user = allUsers.find(u => u._id === evaluator.userId);
        return {
          ...evaluator,
          ...user,
          id: evaluator._id,
          userId: user._id,
          name: evaluator.name,
          role: "Evaluator"
        };
      });

      setStudents(combinedStudents);
      setSupervisors(combinedSupervisors);
      setEvaluators(combinedEvaluators);

      // Auto-show tables if data exists
      if (combinedStudents.length > 0) setViewStudents(true);
      if (combinedSupervisors.length > 0) setViewSupervisors(true);
      if (combinedEvaluators.length > 0) setViewEvaluators(true);

    } catch (err) {
      setError("Failed to fetch users. Please try again.");
      console.error("Error fetching users:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError("");

    try {
      const userData = {
        username: name,
        email,
        password,
        role
      };

      if (editingId) {
        // Update existing user
        await updateUser(editingId, editingType, userData);
      } else {
        // Create new user
        await createUser(userData);
      }

      // Reset form and refresh data
      resetForm();
      await fetchAllUsers();
    } catch (err) {
      setError(err.response?.data?.message || "An error occurred. Please try again.");
      console.error("Error submitting form:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const createUser = async (userData) => {
    // First create the base user
    const userResponse = await axios.post("http://localhost:5000/api/user", userData);
    const userId = userResponse.data._id;

    // Then create the role-specific record
    if (userData.role === "Student") {
      await axios.post("http://localhost:5000/api/student", {
        userId,
        studentName: userData.username,
        regNo: registrationNumber,
        isGrouped: false
      });
    } else if (userData.role === "Supervisor") {
      await axios.post("http://localhost:5000/api/facultyadvisor", {
        userId,
        Name: userData.username,
        Meetings: []
      });
    } else if (userData.role === "Evaluator") {
      await axios.post("http://localhost:5000/api/evaluator", {
        userId,
        name: userData.username
      });
    }
  };

  const updateUser = async (id, type, userData) => {
    // Update the base user
    await axios.patch(`http://localhost:5000/api/user/${userData.userId}`, {
      username: userData.username,
      email: userData.email
    });

    // Update the role-specific record
    if (type === "student") {
      await axios.patch(`http://localhost:5000/api/student/${id}`, {
        studentName: userData.username,
        regNo: registrationNumber
      });
    } else if (type === "supervisor") {
      await axios.patch(`http://localhost:5000/api/facultyadvisor/${id}`, {
        Name: userData.username
      });
    } else if (type === "evaluator") {
      await axios.patch(`http://localhost:5000/api/evaluator/${id}`, {
        name: userData.username
      });
    }
  };

  const handleEdit = (user, type) => {
    setEditingId(user.id);
    setEditingType(type);
    setName(user.name);
    setEmail(user.email);
    setRole(user.role);
    setRegistrationNumber(user.regNo || "");
    setPassword(""); // Don't show password when editing
  };

  const handleResetPassword = async (userId) => {
    const newPassword = prompt("Enter new password:");
    if (newPassword && newPassword.trim() !== "") {
      try {
        await axios.patch(`http://localhost:5000/api/user/${userId}`, {
          password: newPassword
        });
        alert("Password reset successfully!");
        await fetchAllUsers();
      } catch (err) {
        alert("Failed to reset password. Please try again.");
        console.error("Error resetting password:", err);
      }
    }
  };

  const handleDelete = async (id, type, userId) => {
    if (!window.confirm("Are you sure you want to delete this user?")) return;

    try {
      setIsLoading(true);
      
      // First delete the role-specific record
      if (type === "student") {
        await axios.delete(`http://localhost:5000/api/student/${id}`);
      } else if (type === "supervisor") {
        await axios.delete(`http://localhost:5000/api/facultyadvisor/${id}`);
      } else if (type === "evaluator") {
        await axios.delete(`http://localhost:5000/api/evaluator/${id}`);
      }

      // Then delete the base user
      await axios.delete(`http://localhost:5000/api/user/${userId}`);

      alert("User deleted successfully!");
      await fetchAllUsers();
    } catch (err) {
      alert("Failed to delete user. Please try again.");
      console.error("Error deleting user:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const resetForm = () => {
    setName("");
    setEmail("");
    setRole("");
    setRegistrationNumber("");
    setPassword("");
    setEditingId(null);
    setEditingType("");
  };

  return (
    <div className="manage-user-accounts">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />
        <div className="main-content">
          <h1>Manage User Accounts</h1>
          <p>Add or edit accounts for students, supervisors, and evaluators</p>

          {error && <div className="error-message">{error}</div>}
          {isLoading && <div className="loading-message">Loading...</div>}

          <div className="user-form-container">
            <h2>{editingId ? "Edit User" : "Add New User"}</h2>
            <form onSubmit={handleSubmit} className="user-form">
              <label htmlFor="name">Name</label>
              <input
                type="text"
                id="name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required
              />

              <label htmlFor="email">Email</label>
              <input
                type="email"
                id="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                disabled={editingId ? true : false} // Don't allow email changes when editing
              />

              {!editingId && (
                <>
                  <label htmlFor="password">Password</label>
                  <input
                    type="password"
                    id="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                  />
                </>
              )}

              <label htmlFor="role">Role</label>
              <select
                id="role"
                value={role}
                onChange={(e) => setRole(e.target.value)}
                required
                disabled={editingId ? true : false} // Don't allow role changes when editing
              >
                <option value="">Select Role</option>
                <option value="Student">Student</option>
                <option value="Supervisor">Supervisor</option>
                <option value="Evaluator">Evaluator</option>
              </select>

              {role === "Student" && (
                <>
                  <label htmlFor="registrationNumber">
                    Registration Number
                  </label>
                  <input
                    type="text"
                    id="registrationNumber"
                    value={registrationNumber}
                    onChange={(e) => setRegistrationNumber(e.target.value)}
                    required
                  />
                </>
              )}

              <div className="form-buttons">
                <button type="submit" className="submit-btn" disabled={isLoading}>
                  {editingId ? "Update User" : "Create User"}
                </button>
                {editingId && (
                  <button 
                    type="button" 
                    className="cancel-btn"
                    onClick={resetForm}
                    disabled={isLoading}
                  >
                    Cancel
                  </button>
                )}
              </div>
            </form>
          </div>

          {/* Student Table */}
          <div className="table-container">
            <div className="table-header">
              <h2>Student List</h2>
              <button 
                onClick={() => setViewStudents(!viewStudents)}
                className="toggle-btn"
              >
                {viewStudents ? "Hide" : "Show"}
              </button>
            </div>
            {viewStudents && (
              <table>
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Email</th>
                    <th>Registration Number</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {students.length > 0 ? (
                    students.map((student) => (
                      <tr key={student.id}>
                        <td>{student.studentName}</td>
                        <td>{student.email}</td>
                        <td>{student.regNo}</td>
                        <td className="actions">
                          <button 
                            onClick={() => handleEdit(student, "student")}
                            disabled={isLoading}
                          >
                            Edit
                          </button>
                          <button
                            onClick={() => handleResetPassword(student.userId)}
                            disabled={isLoading}
                          >
                            Reset Password
                          </button>
                          <button
                            onClick={() => handleDelete(student.id, "student", student.userId)}
                            disabled={isLoading}
                            className="delete-btn"
                          >
                            Delete
                          </button>
                        </td>
                      </tr>
                    ))
                  ) : (
                    <tr>
                      <td colSpan="4" className="no-data">No students found</td>
                    </tr>
                  )}
                </tbody>
              </table>
            )}
          </div>

          {/* Supervisor Table */}
          <div className="table-container">
            <div className="table-header">
              <h2>Supervisor List</h2>
              <button 
                onClick={() => setViewSupervisors(!viewSupervisors)}
                className="toggle-btn"
              >
                {viewSupervisors ? "Hide" : "Show"}
              </button>
            </div>
            {viewSupervisors && (
              <table>
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Email</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {supervisors.length > 0 ? (
                    supervisors.map((supervisor) => (
                      <tr key={supervisor.id}>
                        <td>{supervisor.Name}</td>
                        <td>{supervisor.email}</td>
                        <td className="actions">
                          <button 
                            onClick={() => handleEdit(supervisor, "supervisor")}
                            disabled={isLoading}
                          >
                            Edit
                          </button>
                          <button
                            onClick={() => handleResetPassword(supervisor.userId)}
                            disabled={isLoading}
                          >
                            Reset Password
                          </button>
                          <button
                            onClick={() => handleDelete(supervisor.id, "supervisor", supervisor.userId)}
                            disabled={isLoading}
                            className="delete-btn"
                          >
                            Delete
                          </button>
                        </td>
                      </tr>
                    ))
                  ) : (
                    <tr>
                      <td colSpan="3" className="no-data">No supervisors found</td>
                    </tr>
                  )}
                </tbody>
              </table>
            )}
          </div>

          {/* Evaluator Table */}
          <div className="table-container">
            <div className="table-header">
              <h2>Evaluator List</h2>
              <button 
                onClick={() => setViewEvaluators(!viewEvaluators)}
                className="toggle-btn"
              >
                {viewEvaluators ? "Hide" : "Show"}
              </button>
            </div>
            {viewEvaluators && (
              <table>
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Email</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {evaluators.length > 0 ? (
                    evaluators.map((evaluator) => (
                      <tr key={evaluator.id}>
                        <td>{evaluator.name}</td>
                        <td>{evaluator.email}</td>
                        <td className="actions">
                          <button 
                            onClick={() => handleEdit(evaluator, "evaluator")}
                            disabled={isLoading}
                          >
                            Edit
                          </button>
                          <button
                            onClick={() => handleResetPassword(evaluator.userId)}
                            disabled={isLoading}
                          >
                            Reset Password
                          </button>
                          <button
                            onClick={() => handleDelete(evaluator.id, "evaluator", evaluator.userId)}
                            disabled={isLoading}
                            className="delete-btn"
                          >
                            Delete
                          </button>
                        </td>
                      </tr>
                    ))
                  ) : (
                    <tr>
                      <td colSpan="3" className="no-data">No evaluators found</td>
                    </tr>
                  )}
                </tbody>
              </table>
            )}
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default ManageUserAccounts;
